    while (v::modules::speed::used || v::modules::reach::used || v::modules::fly::used || v::modules::nametags::used ||
           v::modules::timer::used || v::modules::esp::used || v::modules::cavefinder::used || v::modules::bhop::used ||
           v::modules::velocity::used) {
