			if (row[k] == c)
				return true;
		}
		return false;
	}
	bool isInCol(vector<vector<char>>& board, int j, char c)
	{
		for (int k = 0; k < 9; k++)
		{
			if (board[k][j] == c)
				return true;
		}
		return false;
	}
	bool isInRec(vector<vector<char>>& board, int i, int j, char c)
	{
