            popu=new Popu();
            bestRouteP4=popu->init(bestRouteP4,false);
            delete popu;
            bestRoute.clear();
            bestRoute<<bestRouteP1<<bestRouteP2<<bestRouteP3<<bestRouteP4;

        }
        Popu *popu=new Popu();
