        tpLength=popu->totalRoute;
        qDebug()<<"After GA:"<<tpLength;
        delete popu; ///isn't this done automatically as popu is in the if scope ?
    }

    /// @todo separte this part as an indepandant function
    int i=0;
    procededLoops.clear();
