            inPtr = inDoublePtr;
        }
        /* align inPtr to 8 bytes boundary. Will not align outPtr */

#if defined(osx_platform)
        /* osx does not align */
        outPtr = alignInt( outPtr );
#else
        outPtr = alignDouble( outPtr );
#endif

        memcpy( outPtr, origDoublePtr, sizeof( rodsLong_t ) * numElement );
        free( origDoublePtr );

        return 0;
    }

