{
	char temp[500], *pos, *newpos; //turetu pakakti 480
	strcpy(temp, TrSakinys);

	int i = 0;
	pos = strtokf(temp, "+- ", &newpos);
	while (pos != NULL)
	{
		units[i] = fv2id(pos);
		pos = strtokf(NULL, "+- ", &newpos);
		if (pos == NULL) unitseparators[i] = '+';
		else unitseparators[i] = TrSakinys[pos - temp - 1];
		i++;
	}

	return i;
}

