    if (read_ret == -1) {
        fprintf(stderr, "Unexpected error read [errno=%d, errstr=%s] at %s:%d",
            read_ret, strerror(errno), __FILE__, __LINE__);
        exit(EXIT_FAILURE);
    }
    close(fd);

    struct fatBinaryHeader *fbh = (struct fatBinaryHeader *)fatbin;
