    }
    fd = fatfunction_fd_load;

    void *func_id = NULL;
    size_t size = 0;
    int exists = 0;
    char *deviceFun = NULL;
    char *deviceName = NULL;
    int thread_limit;
    uint3 *tid = NULL;
    uint3 *bid = NULL;
    dim3 *bDim = NULL;
    dim3 *gDim = NULL;
