            DEBUG_PRINT("Finish reading functions for fatbin-%d.ava\n", fatbin_num);
            break;
        }
        if (read_ret == -1) {
            fprintf(stderr, "Unexpected error read [errno=%d, errstr=%s] at %s:%d",
