        a.resize(1 << n); b.resize(a.size());
        for(int i=0; i<a.size(); i++) cin >> a[i];
        for(int i=0; i<(1<<n); i++){
            int sum = 0;
            for(int j=0; (i ^ (1<<j)) < a.size(); j++){
                sum += a[(i ^ (1<<j))];
            }
            b[i] = sum;
        }
        int max1 = -1;
        for(int i=0; i<a.size(); i++){
            for(int j=0; (i ^ (1<<j)) < a.size(); j++){
                max1 = max(max1, (int)b[i] + (int)b[i^(1<<j)]);
            }
        }
        cout << max1 << "\n";
    }
    return 0;
}

