};

struct Cluster {
    Cluster() {
        center.setZero();
        center_orig.setZero();
        bbox_min = {std::numeric_limits<float>::max(),
                    std::numeric_limits<float>::max(),
                    std::numeric_limits<float>::max()};
        bbox_max = -bbox_min;
    }
    Eigen::Vector3f center;
    Eigen::Vector3f center_orig;
