void circulo(float raio, float cx, float cy, int tipo)
{
    float ang, x, y;

    glColor3f(0, 1, 0);
    if (tipo == 1)
    {

        glBegin(GL_POLYGON);
        for (int i = 0; i < 360; i++)
        {
            ang = (i * M_PI) / 180.0;
            x = cx + (cos(ang) * raio);
            y = cy + (sin(ang) * raio);
            glVertex2f(x, y);
        }
        glEnd();
    }
    else
    {
        glColor3f(0, 1, 0);
        glBegin(GL_LINE_LOOP);
        for (int i = 0; i < 360; i++)
        {
            ang = (i * M_PI) / 180.0;
            x = cx + (cos(ang) * raio);
            y = cy + (sin(ang) * raio);
            glVertex2f(x, y);
        }
        glEnd();
    }
}

