int cmp(const void *a, const void *b)
{
	if (*((int*)a + 1) != *((int*)b + 1)) return -( *((int*)a + 1) - *((int*)b + 1) );
	else
	{
		int na = *(int*)a;
		int nb = *(int*)b;
		char sa[15], sb[15];
		int i = 0;
		while(na)
		{
			sa[i++] = na % 10 + '0';
			na /= 10; 
		} 
		sa[i] = '\0';
		for (int j = 0; j <= (i - 1) / 2; j++)
		{
			char temp = sa[j];
			sa[j] = sa[i - 1 - j];
			sa[i - 1 - j] = temp; 
		}
		//printf ("%s\n", sa);

		i = 0;
		while(nb)
		{
			sb[i++] = nb % 10 + '0';
			nb /= 10;
		}
		sb[i]= '\0';
		for (int j = 0; j <= (i - 1) / 2; j++)
		{
			char temp = sb[j];
			sb[j] = sb[i - 1 - j];
			sb[i - 1 - j] = temp;
		}
		int len1 = strlen(sa), len2 = strlen(sb);
